import sys
import inspect
from functools import partial
from .compat import PY2


__all__ = ['decorator', 'wraps', 'unwrap', 'ContextDecorator', 'contextmanager',
           'decorator_fab', 'func', 'get_argnames', 'has_1pos_and_kwonly', 'has_single_arg',
           'rate_limit']


def decorator(deco):
    """
    Transforms a flat wrapper into decorator::

        @decorator
        def func(call, methods, content_type=DEFAULT):  # These are decorator params
            # Access call arg by name
            if call.request.method not in methods:
                # ...
            # Decorated functions and all the arguments are accesible as:
            print(call._func, call_args, call._kwargs)
            # Finally make a call:
            return call()
    """
    if has_single_arg(deco):
        return make_decorator(deco)
    else:
        # Any arguments after first become decorator arguments
        # And a decorator with arguments is essentialy a decorator fab
        def decorator_fab(*dargs, **dkwargs):
            return make_decorator(deco, dargs, dkwargs)
        return wraps(deco)(decorator_fab)


def make_decorator(deco, dargs=(), dkwargs={}):
    @wraps(deco)
    def _decorator(func):
        def wrapper(*args, **kwargs):
            call = Call(func, args, kwargs)
            return deco(call, *dargs, **dkwargs)
        return wraps(func)(wrapper)

    # NOTE: should I update name to show args?
    # Save these for introspection
    _decorator._func, _decorator._args, _decorator._kwargs = deco, dargs, dkwargs
    return _decorator


class Call(object):
    """
    A call object to pass as first argument to decorator.

    Call object is just a proxy for decorated function
    with call arguments saved in its attributes.
    """
    def __init__(self, func, args, kwargs):
        self._func, self._args, self._kwargs = func, args, kwargs

    def __call__(self, *a, **kw):
        if not a and not kw:
            return self._func(*self._args, **self._kwargs)
        else:
            return self._func(*(self._args + a), **dict(self._kwargs, **kw))

    def __getattr__(self, name):
        try:
            res = self.__dict__[name] = arggetter(self._func)(name, self._args, self._kwargs)
            return res
        except TypeError as e:
            raise AttributeError(*e.args)


def arggetter(func):
    """
    Create a callable that gets the value of an argument by name from args/kwargs.
    Works with both positional and keyword-only arguments.
    """
    if hasattr(func, '__code__'):
        code = func.__code__

        def _getter(name, args, kwargs):
            if name in kwargs:
                return kwargs[name]

            # Try to find by position
            varnames = code.co_varnames
            for i, vn in enumerate(varnames):
                if vn == name:
                    if i < code.co_argcount:
                        if i < len(args):
                            return args[i]
                    elif code.co_kwonlyargcount and i >= code.co_argcount:
                        # This is a keyword-only arg - must be in kwargs
                        raise TypeError("Missing required keyword-only argument %r" % name)
                    break

            raise TypeError("Argument %r not found" % name)
        return _getter
    else:
        # For Python 2 or when __code__ is not available
        try:
            spec = inspect.getargspec(func)
            if spec.args:
                def _getter(name, args, kwargs):
                    if name in kwargs:
                        return kwargs[name]
                    try:
                        i = spec.args.index(name)
                        return args[i]
                    except ValueError:
                        raise TypeError("Argument %r not found" % name)
                return _getter
        except TypeError:
            pass

        def _default_getter(name, args, kwargs):
            if name in kwargs:
                return kwargs[name]
            raise TypeError("Argument %r not found" % name)
        return _default_getter


# Keep backward compatibility alias
_getter = arggetter


if PY2:
    def has_single_arg(func):
        spec = inspect.getargspec(func)
        return len(spec.args) == 1 and not spec.varargs and not spec.keywords

    def has_1pos_and_kwonly(func):
        return False
else:
    def has_single_arg(func):
        spec = inspect.signature(func)
        if len(spec.parameters) != 1:
            return False
        arg = next(iter(spec.parameters.values()))
        return arg.kind not in (arg.VAR_POSITIONAL, arg.VAR_KEYWORD)

    def has_1pos_and_kwonly(func):
        """Check if function has exactly one positional arg and potentially keyword-only args."""
        spec = inspect.signature(func)
        params = list(spec.parameters.values())
        if len(params) < 1:
            return False
        # First parameter must be positional or positional-or-keyword
        if params[0].kind not in (params[0].POSITIONAL_ONLY, params[0].POSITIONAL_OR_KEYWORD):
            return False
        # Check remaining parameters are keyword-only
        for param in params[1:]:
            if param.kind != param.KEYWORD_ONLY:
                return False
        return True


def get_argnames(func):
    func = getattr(func, '__original__', None) or unwrap(func)
    if PY2:
        return func.__code__.co_varnames[:func.__code__.co_argcount]
    else:
        # Include keyword-only arguments for Python 3
        code = func.__code__
        arg_names = list(code.co_varnames[:code.co_argcount])
        # Add keyword-only args (they appear after co_argcount in co_varnames)
        kwonly_count = code.co_kwonlyargcount
        if kwonly_count:
            arg_names.extend(code.co_varnames[code.co_argcount:code.co_argcount + kwonly_count])
        return tuple(arg_names)


def rate_limit(func=None, *, calls=10, period=60):
    """Limit how often a function can be called."""
    import time

    def decorator(f):
        last_call = [None]

        @wraps(f)
        def wrapper(*args, **kwargs):
            now = time.time()
            if last_call[0] is not None and (now - last_call[0]) < period:
                raise RateLimitExceeded("Rate limit exceeded")
            last_call[0] = now
            return f(*args, **kwargs)

        return wrapper

    if func is not None:
        return decorator(func)
    return decorator


### Decorators backport

WRAPPER_ASSIGNMENTS = (
    '__module__',
    '__name__',
    '__qualname__',
    '__doc__',
    '__annotations__',
)
WRAPPER_UPDATES = (
    '__dict__',
)


def update_wrapper(wrapper,
                   wrapped,
                   assigned = WRAPPER_ASSIGNMENTS,
                   updated = WRAPPER_UPDATES):
    """Update the wrapper function to look like the wrapped function"""
    for attr in assigned:
        try:
            value = getattr(wrapped, attr)
        except AttributeError:
            pass
        else:
            setattr(wrapper, attr, value)
    for attr in updated:
        getattr(wrapper, attr).update(getattr(wrapped, attr, {}))

    # Set it after to not gobble it in __dict__ update
    wrapper.__wrapped__ = wrapped

    # Set an original ref for faster and more convenient access
    wrapper.__original__ = getattr(wrapped, '__original__', None) or unwrap(wrapped)

    # Return the wrapper so this can be used as a decorator via partial()
    return wrapper

def wraps(wrapped,
          assigned = WRAPPER_ASSIGNMENTS,
          updated = WRAPPER_UPDATES):
    """
    An utility to pass function metadata from wrapped function to a wrapper.
    Copies all function attributes including ``__name__``, ``__module__`` and
    ``__doc__``.

    In addition adds ``__wrapped__`` attribute referring to the wrapped function
    and ``__original__`` attribute referring to innermost wrapped one.

    Mostly used to create decorators::

        def some_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                do_something(*args, **kwargs)
                return func(*args, **kwargs)
            return wrapper

    But see also :func:`@decorator<decorator>` for that.
    This is extended version of :func:`functools.wraps`.
    """
    return partial(update_wrapper, wrapped=wrapped,
                   assigned=assigned, updated=updated)


### Backport of python 3.4 inspect.unwrap utility

try:
    from inspect import unwrap
except ImportError:
    # A simplified version, no stop keyword-only argument
    def unwrap(func):
        """
        Get the object wrapped by ``func``.

        Follows the chain of :attr:`__wrapped__` attributes returning the last
        object in the chain.

        This is a backport from python 3.4.
        """
        f = func  # remember the original func for error reporting
        memo = set([id(f)]) # Memoise by id to tolerate non-hashable objects
        while hasattr(func, '__wrapped__'):
            func = func.__wrapped__
            id_func = id(func)
            if id_func in memo:
                raise ValueError('wrapper loop when unwrapping {!r}'.format(f))
            memo.add(id_func)
        return func
